    "teams-live-captions.html",
    "discord-twitch-subtitles.html"
)

$translations = New-Object "System.Collections.Generic.List[object]"

function Add-Row {
    param(
        [Parameter(Mandatory = $true)][string]$en,
        [Parameter(Mandatory = $true)][string]$ru,
        [Parameter(Mandatory = $true)][string]$fr,
        [Parameter(Mandatory = $true)][string]$es,
        [Parameter(Mandatory = $true)][string]$de,
        [Parameter(Mandatory = $true)][string]$pt
    )

    $script:translations.Add([pscustomobject]@{
        en = $en
        ru = $ru
        fr = $fr
        es = $es
        de = $de
        pt = $pt
    }) | Out-Null
}

