function Apply-Translations {
    param(
        [Parameter(Mandatory = $true)][string]$content,
        [Parameter(Mandatory = $true)][string]$lang
    )

    $rows = $translations | Sort-Object { $_.en.Length } -Descending
    foreach ($row in $rows) {
        $replacement = $row.$lang
        if ([string]::IsNullOrEmpty($replacement)) {
            continue
        }
        $content = $content.Replace($row.en, $replacement)
    }
    return $content
}

$utf8NoBom = New-Object System.Text.UTF8Encoding($false)
$changed = 0

foreach ($lang in $languages) {
    foreach ($page in $pages) {
        $path = Join-Path $PSScriptRoot "$lang\$page"
        if (-not (Test-Path $path)) {
            Write-Warning "Missing file: $path"
            continue
        }

        $original = [System.IO.File]::ReadAllText($path)
        $translated = Apply-Translations -content $original -lang $lang

        if ($translated -ne $original) {
            [System.IO.File]::WriteAllText($path, $translated, $utf8NoBom)
            $changed++
        }
    }
}

Write-Host "Translated files updated: $changed"
